window.docContents[243].resolve({"/Planned-constructions/UD-III/#Core-C______--Planned-constructions--UD-III":{"contents":"The local reference int& y = x binds a second name to the same location, without allocating.\n\nThe judgment  extends to v[i], o.field, p->field and *p. An index out of bounds and the dereference of nullptr are error.\n\n","context":"Core C++\u0009Planned constructions","header":"6.1. UD III","id":"/Planned-constructions/UD-III/#Core-C______--Planned-constructions--UD-III"}});